526:     \centering
527:     \includegraphics[width=\linewidth]{fig_toomreq.eps}
528:     \caption{Toomre $Q$ parameter of the gas disc of NGC~300 as a function of galactocentric radius.}
529:     \label{fig_toomreq}
530:   \end{figure}
